import { mkdir, readFile, writeFile } from 'node:fs/promises';
const root = new URL('../', import.meta.url);
const content = await readFile(new URL('docs/chatgpt-sites-knowledge.md', root), 'utf8');
await mkdir(new URL('chatgpt/', root), { recursive: true });
await writeFile(new URL('chatgpt/goal-clicker-project-knowledge.md', root),
  '<!-- Generated by scripts/export-chatgpt-knowledge.mjs from docs/chatgpt-sites-knowledge.md. -->\n\n' + content.trimEnd() + '\n');
console.log('Updated chatgpt/goal-clicker-project-knowledge.md');
